async function scanBundle(input, deliver) {
  let delivered = 0;
  let lineNumber = 0;
  let line = "";
  const decoder = new TextDecoder("utf-8");

  const processLine = async (text, number) => {
    if (/^[\u0009\u000d\u0020]*$/.test(text)) return false;

    let value;
    try {
      value = JSON.parse(text);
    } catch {
      const error = new Error(`Invalid JSON on line ${number}`);
      error.code = "BAD_LINE";
      error.line = number;
      throw error;
    }

    delivered++;
    return (await deliver(value, number)) === false;
  };

  const consume = async (text) => {
    for (let i = 0; i < text.length; i++) {
      const character = text[i];

      if (character === "\n") {
        lineNumber++;
        const content = line.endsWith("\r")
          ? line.slice(0, -1)
          : line;
        line = "";

        if (await processLine(content, lineNumber)) {
          return true;
        }
      } else {
        line += character;
      }
    }

    return false;
  };

  try {
    while (true) {
      const chunk = await input.read();

      if (chunk === null) {
        if (await consume(decoder.decode())) {
          return delivered;
        }

        if (line !== "") {
          lineNumber++;
          await processLine(line, lineNumber);
        }

        return delivered;
      }

      if (await consume(decoder.decode(chunk, { stream: true }))) {
        return delivered;
      }
    }
  } finally {
    await input.close();
  }
}
